create table profiles(id uuid primary key references auth.users on delete cascade, username text unique, display_name text, bio text, skills text[] default '{}', role text not null default 'member' check (role in ('member','moderator','org_manager','admin')), created_at timestamptz default now());
create table requests(id uuid primary key default gen_random_uuid(), owner uuid not null references profiles on delete cascade default auth.uid(), title text not null check (char_length(title) between 5 and 120), description text not null, category text not null, assistance text not null default 'free', skills text[] default '{}', status text not null default 'open' check (status in ('draft','open','responses_received','matched','in_progress','completed','cancelled','closed')), created_at timestamptz default now());
create table offers(id uuid primary key default gen_random_uuid(), owner uuid not null references profiles on delete cascade default auth.uid(), title text not null check (char_length(title) between 5 and 120), description text not null, category text not null, arrangement text not null default 'free', skills text[] default '{}', active boolean default true, created_at timestamptz default now());
create table request_responses(id uuid primary key default gen_random_uuid(), request_id uuid not null references requests on delete cascade, responder uuid not null references profiles on delete cascade default auth.uid(), message text not null, created_at timestamptz default now(), unique(request_id, responder));
create index on requests(status, created_at desc); create index on offers(active, created_at desc);
alter table profiles enable row level security; alter table requests enable row level security; alter table offers enable row level security; alter table request_responses enable row level security;
create policy "profiles readable" on profiles for select to authenticated using (true);
create policy "own profile update" on profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid() and role=(select role from profiles where id=auth.uid()));
create policy "open requests readable" on requests for select to authenticated using (status<>'draft' or owner=auth.uid());
create policy "own requests insert" on requests for insert to authenticated with check (owner=auth.uid());
create policy "own requests update" on requests for update to authenticated using (owner=auth.uid()) with check (owner=auth.uid());
create policy "active offers readable" on offers for select to authenticated using (active or owner=auth.uid());
create policy "own offers insert" on offers for insert to authenticated with check (owner=auth.uid());
create policy "own offers update" on offers for update to authenticated using (owner=auth.uid()) with check (owner=auth.uid());
create policy "own offers delete" on offers for delete to authenticated using (owner=auth.uid());
create policy "responses visible to parties" on request_responses for select to authenticated using (responder=auth.uid() or exists(select 1 from requests r where r.id=request_id and r.owner=auth.uid()));
create policy "respond to others" on request_responses for insert to authenticated with check (responder=auth.uid() and not exists(select 1 from requests r where r.id=request_id and r.owner=auth.uid()));
create function handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,display_name,username) values(new.id, coalesce(new.raw_user_meta_data->>'name', split_part(new.email,'@',1)), split_part(new.email,'@',1)||'_'||substr(new.id::text,1,4)); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_new_user();
